SELECT r.request_id AS requestId, r.title AS title, r.status AS status, r.priority AS priority, requester.name AS requesterName, assignee.name AS assigneeName, r.created_at AS createdAt FROM requests r JOIN users requester ON r.requester_id = requester.user_id LEFT JOIN users assignee ON r.assignee_id = assignee.user_id
AND r.status = #{status}
AND r.priority = #{priority}
AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR r.content LIKE CONCAT('%', #{keyword}, '%') OR requester.name LIKE CONCAT('%', #{keyword}, '%') OR assignee.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.created_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM requests r JOIN users requester ON r.requester_id = requester.user_id LEFT JOIN users assignee ON r.assignee_id = assignee.user_id
AND r.status = #{status}
AND r.priority = #{priority}
AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR r.content LIKE CONCAT('%', #{keyword}, '%') OR requester.name LIKE CONCAT('%', #{keyword}, '%') OR assignee.name LIKE CONCAT('%', #{keyword}, '%'))
